STRIDE_KEYWORDS = {
    "spoofing": ["fake credentials", "impersonate", "forged token"],
    "tampering": ["modify request", "alter data", "change price"],
    "repudiation": ["deny sending", "no audit log", "delete logs"],
    "information_disclosure": ["leak", "expose data", "read another user"],
    "denial_of_service": ["flood", "exhaust", "overload"],
    "elevation_of_privilege": ["become admin", "bypass authorization", "escalate role"],
}


def classify(threat_description):
    text = threat_description.lower()
    matches = [
        category
        for category, keywords in STRIDE_KEYWORDS.items()
        if any(keyword in text for keyword in keywords)
    ]
    return matches or ["sin_categoria"]


threats = [
    "An attacker uses a forged token to impersonate the billing service",
    "A user can read another user's order by changing the id in the URL",
    "A script floods the login endpoint to exhaust the connection pool",
]

for threat in threats:
    print(f"{threat} -> {classify(threat)}")
